from qutip import piqs
try:
    ops = piqs.jspin(4)
    print("jspin(4) returns:", type(ops))
    if isinstance(ops, tuple) or isinstance(ops, list):
        print("Length:", len(ops))
        print("First element shape:", ops[0].shape)
    else:
        print("Shape:", ops.shape)
except Exception as e:
    print("Error:", e)

try:
    jx = piqs.jspin(4, 'x')
    print("jspin(4, 'x') shape:", jx.shape)
except Exception as e:
    print("Error with 'x':", e)
